<?php
require_once __DIR__.'/../includes/init.php';require_login();$page_title='Question Papers';$exams=$pdo->query('SELECT id,exam_name FROM examinations ORDER BY id DESC')->fetchAll();$err='';
if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();try{$file=upload_file('paper',['application/pdf'=>'pdf'],15728640);if(!$file)throw new RuntimeException('Select a PDF file.');$q=$pdo->prepare('INSERT INTO question_papers(examination_id,class_name,subject_name,stored_file,uploaded_by) VALUES(?,?,?,?,?)');$q->execute([(int)$_POST['exam_id'],trim($_POST['class_name']),trim($_POST['subject_name']),$file,$_SESSION['user_id']]);flash('Paper uploaded securely.');go('exams/papers.php');}catch(Throwable $e){$err=$e->getMessage();}}
$rows=$pdo->query('SELECT p.id,e.exam_name,p.class_name,p.subject_name,p.stored_file,p.created_at FROM question_papers p JOIN examinations e ON e.id=p.examination_id ORDER BY p.id DESC')->fetchAll();require __DIR__.'/../includes/header.php';?><h1>Question Paper Archive</h1><?php if($err):?><div class="notice error"><?=h($err)?></div><?php endif;?><div class="panel"><form method="post" enctype="multipart/form-data"><input type="hidden" name="csrf" value="<?=h(csrf())?>"><label>Examination</label><select name="exam_id" required><?php foreach($exams as $e):?><option value="<?=$e['id']?>"><?=h($e['exam_name'])?></option><?php endforeach;?></select><label>Class</label><input name="class_name" required><label>Subject</label><input name="subject_name" required><label>Question paper (PDF only, max 15 MB)</label><input type="file" name="paper" accept="application/pdf" required><button>Upload paper</button></form></div><div class="panel"><table><tr><th>Exam</th><th>Class</th><th>Subject</th><th>Uploaded</th></tr><?php foreach($rows as $r):?><tr><td><?=h($r['exam_name'])?></td><td><?=h($r['class_name'])?></td><td><?=h($r['subject_name'])?></td><td><?=h($r['created_at'])?></td></tr><?php endforeach;?></table></div><?php require __DIR__.'/../includes/footer.php';?>